CREATE FUNCTION reference_eval(statement text) RETURNS jsonb LANGUAGE plpgsql AS $$
    DECLARE output jsonb; code text; message text; detail text; hint text;
    BEGIN EXECUTE statement INTO output; RETURN jsonb_build_object('orders',output);
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS code=RETURNED_SQLSTATE,message=MESSAGE_TEXT,detail=PG_EXCEPTION_DETAIL,hint=PG_EXCEPTION_HINT;
    RETURN jsonb_build_object('error',jsonb_build_object('sqlstate',code,'message',message,'detail',detail,'hint',hint)); END $$
